#include <fstream>
#include <vector>
#include <string>

// Function to handle file selection and path saving
void handleFileSelection() {
    // Open file dialog
    std::string filePath = openFileDialog(); // Assume this function opens a file dialog and returns the selected path

    // Save the path using emplace
    std::vector<std::string> paths;
    paths.emplace_back(filePath);

    // Save the path to a file
    std::ofstream file("paths.txt");
    if (file.is_open()) {
        for (const auto& path : paths) {
            file << path << std::endl;
        }
        file.close();
    }

    // Thank the user
    std::cout << "Thank you for providing the file path." << std::endl;
}
